  Object.keys(val).forEach(k => { info[k] = val[k] === String(a[k] || '').trim() ? '' : val[k]; }); info.siNext = pxNum(v('su-sinext').value) || 0; // auto ang hindi binago
  const sites = Object.assign({}, PX.cfg.sites || {}); sites[PX.site] = info;
