  box.innerHTML = r.map((m, i) => `<div onclick="pxMcSel(${i})" style="padding:.5rem;border:1px solid #e2e8f0;border-radius:.4rem;margin-bottom:.2rem;cursor:pointer;display:flex;justify-content:space-between;gap:.4rem;"><span><b>${pxE(m.name)}</b> · ${pxE(m.mid)} <small>${pxE(m.club)}</small></span>${pxMemBadge(m)}</div>`).join('') || (q ? '<small style="color:#94a3b8;">Walang tugma. Idagdag sa Members tab kung bago.</small>' : '');
