const pxTabsOpen = () => (PX.tabs || []).filter(t => t.status === 'open');
const pxTabOf = tid => pxTabsOpen().find(t => t.tableId === tid);
const pxTabLines = t => { const M = {}; (t.orders || []).forEach(o => { if (o.status === 'void') return; (o.items || []).forEach(l => { const k = l.id + '|' + l.price; if (!M[k]) M[k] = { id: l.id, name: l.name, price: +l.price, qty: 0 }; M[k].qty += +l.qty; }); }); return Object.keys(M).map(k => M[k]); };
