async function pxTabsLoad() { try { const s = await db.collection('pos_tabs').where('site', '==', PX.site).where('status', '==', 'open').get(); PX.tabs = []; s.forEach(x => PX.tabs.push(Object.assign({ id: x.id }, x.data()))); } catch (e) { PX.tabs = PX.tabs || []; } }
