  clearInterval(PX._fi); PX._fi = setInterval(() => { const m = document.getElementById('px-modal'); if (PX.tab === 'tables' && !PX.fedit && !(m && m.style.display !== 'none' && m.innerHTML) && !document.querySelector('[id^="px-d"][style*="flex"]')) pxBody(); }, 25000);
