    const tb = pxTabOf(t.id), sh = t.shape || 'sq', sz = PX_SHP[sh] || PX_SHP.sq, w = t.w || sz.w, h = t.h || sz.h, col = tb ? '#fed7aa' : '#bbf7d0', bd = tb ? '#ea580c' : '#16a34a';
